import{_ as d,o,c as e,a2 as a}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Gemini 多镜头叙事与转场","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-multi-shot-narrative.md","filePath":"tools/gemini-multi-shot-narrative.md","lastUpdated":1787714366000}'),i={name:"tools/gemini-multi-shot-narrative.md"};function r(s,t,n,l,h,c){return o(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="gemini-多镜头叙事与转场" tabindex="-1">Gemini 多镜头叙事与转场 <a class="header-anchor" href="#gemini-多镜头叙事与转场" aria-label="Permalink to &quot;Gemini 多镜头叙事与转场&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及 Veo 对分镜/转场的支持请以官方文档为准。</li></ul></div><blockquote><p>提问：</p><ol><li>8 个分镜之间怎么设计转场节奏，避免拼接感？有没有镜头与镜头衔接、保持情绪连贯的技巧？</li><li>一条 30 秒食品广告的完整结构（吸引 → 展示 → 食欲 → 品牌收尾）该怎么拆给 Gemini 分镜？</li></ol></blockquote><h2 id="_8-分镜转场节奏-「起-承-转-合」律动" tabindex="-1">8 分镜转场节奏（「起-承-转-合」律动） <a class="header-anchor" href="#_8-分镜转场节奏-「起-承-转-合」律动" aria-label="Permalink to &quot;8 分镜转场节奏（「起-承-转-合」律动）&quot;">​</a></h2><p>AI 视频极易因「镜头时长一致」产生机械拼接感，核心在于<strong>快慢交替（抑扬顿挫）</strong>：</p><table tabindex="0"><thead><tr><th>分镜</th><th>画面</th><th>节奏</th><th>转场手法</th></tr></thead><tbody><tr><td>01</td><td>宏观环境引子（国潮场景）</td><td>慢 1.5–2s</td><td>Match Cut，画面中央留焦点</td></tr><tr><td>02</td><td>食材特写（黄油融化 / 番茄爆汁）</td><td>中 1s</td><td>微距推镜，液体/粉末同向运动衔接</td></tr><tr><td>03</td><td>制作过程（油锅翻滚）</td><td>快 0.8s</td><td>气泡/烟雾遮挡做 Wipe Cut</td></tr><tr><td>04</td><td>调味瞬间（粉末瀑布倾泻）</td><td>极慢 2s</td><td>Shape/Color Match 匹配粉末落点</td></tr><tr><td>05</td><td>成品亮相</td><td>中 1s</td><td>轴线/方向延续</td></tr><tr><td>06</td><td>开袋/开盒（手撕包装）</td><td>快 0.8s</td><td>Action Cut，撕开瞬间切下一镜</td></tr><tr><td>07</td><td>品尝反馈（蘸酱/咬下高潮）</td><td>慢 1.5s</td><td>光效/粒子转场</td></tr><tr><td>08</td><td>品牌落款（包装 + Logo 定格）</td><td>稳 1.5s</td><td>自然淡出 / 图形归位</td></tr></tbody></table><h2 id="四大无缝衔接技巧" tabindex="-1">四大无缝衔接技巧 <a class="header-anchor" href="#四大无缝衔接技巧" aria-label="Permalink to &quot;四大无缝衔接技巧&quot;">​</a></h2><ol><li><strong>动向一致性（Vector Continuation）</strong>：上一镜结尾运动方向 = 下一镜开头方向（镜头 03 向下俯冲 → 镜头 04 顺势向下）。</li><li><strong>遮挡 / 擦除转场（Wipe）</strong>：用烟雾、蒸汽、飞沫或主体边缘短暂遮挡全屏再切换（番茄汁溅满屏 → 下一帧从粉末瀑布拉出）。</li><li><strong>形状 / 颜色匹配（Match Cut）</strong>：整颗番茄（圆）→ 番茄味薯圈（圆）；黄油块（旋转）→ 金黄薯条。</li><li><strong>声画同步驱动（Audio-Driven Pacing）</strong>：剪辑点踩在音效上——<code>Crunch</code> 配画面放大/微闪光，液体流动声配慢动作微距。</li></ol><h2 id="保持情绪连贯的「三个不变」" tabindex="-1">保持情绪连贯的「三个不变」 <a class="header-anchor" href="#保持情绪连贯的「三个不变」" aria-label="Permalink to &quot;保持情绪连贯的「三个不变」&quot;">​</a></h2><p>每个分镜 Prompt 固定三样，8 镜头即有统一品牌调性：</p><ul><li><strong>统一光影</strong>：<code>warm volumetric lighting, cinematic soft backlight, golden hour food photography style</code></li><li><strong>统一色调</strong>：蜂蜜黄油 → <code>warm golden, amber yellow, creamy white</code>；番茄 → <code>vibrant tomato red, warm lighting</code></li><li><strong>统一相机参数</strong>：<code>shot on 85mm macro lens, shallow depth of field, 4K resolution, commercial food advertisement</code></li></ul><h2 id="_30-秒广告四阶段拆解" tabindex="-1">30 秒广告四阶段拆解 <a class="header-anchor" href="#_30-秒广告四阶段拆解" aria-label="Permalink to &quot;30 秒广告四阶段拆解&quot;">​</a></h2><p>先给 Gemini 一段<strong>全局视觉基线</strong>：<code>Commercial food photography, 8k resolution, cinematic lighting, photorealistic, ultra-detailed texture, 60fps</code> + 统一色调 + 主角产品定义。再按四阶段拆：</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>目标</th><th>画面</th><th>运镜</th></tr></thead><tbody><tr><td>黄金 3 秒钩子</td><td>0–3s</td><td>秒内抓眼球</td><td>极限微距 + 慢动作（薯条蘸酱拉丝）</td><td><code>Macro lens, 120fps, push-in</code></td></tr><tr><td>场景与产品展示</td><td>3–10s</td><td>建立场景共鸣</td><td>动态中景 + 真实生活感（开袋）</td><td><code>Medium tracking shot</code></td></tr><tr><td>食欲爆发</td><td>10–22s</td><td>放大美味感</td><td>动态特写 + 原材料碰撞（融化/爆汁/飞溅）</td><td><code>Orbit shot / Phantom flex macro</code></td></tr><tr><td>情绪升华与品牌收尾</td><td>22–30s</td><td>满足感 + Logo + CTA</td><td>满足表情 + 包装 hero-shot + Logo</td><td><code>Shallow DOF close-up → static tilt-up</code></td></tr></tbody></table><p><strong>可直接复制给 Gemini 的整体指令</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一位精通 AI 视频生成的食品广告导演（熟悉 Google Veo / Sora 提示词）。</span></span>
<span class="line"><span>请为一款【中式番茄味 / 蜂蜜黄油味薯条】创作一条 30 秒的短视频广告脚本。</span></span>
<span class="line"><span>格式：</span></span>
<span class="line"><span>1. 按 [0-3s 钩子] [3-10s 场景] [10-22s 食欲爆发] [22-30s 品牌收尾] 拆解。</span></span>
<span class="line"><span>2. 每个镜头提供：画面描述(Visual) / 运镜指令(Camera) / 光影材质细节 / 可直接复制给 Veo 的英文 Prompt。</span></span></code></pre></div><hr><p>关联：分镜的结构方法论见 <a href="/method/storyboard">分镜设计</a> 与 <a href="/method/workflow-sop">从 brief 到成片 SOP</a> 的 ④ 分镜阶段；单镜头内相机/主体/物理三层不再打架见 <a href="/tools/gemini-motion-layers">三层运动解耦</a>。</p>`,18)])])}const g=d(i,[["render",r]]);export{m as __pageData,g as default};
